        "text": "Investigate underlying precipitants (e.g., cold bathroom temperature, fear of water spray, undressed vulnerability, arthritis pain); modify the routine by warming the room, playing preferred relaxing music, using a towel bath or gentle sponge bath, and scheduling pre-wash analgesia"
